export const USING_AI_WISELY_ACTIVITIES = [
{n:1,type:"mcq",micro:"Masukan membentuk keluaran",q:"Kualitas jawaban dari AI percakapan sangat dipengaruhi oleh...",options:["Seberapa jelas & lengkap pertanyaan/instruksi yang kamu berikan","Waktu kamu bertanya","Keberuntungan"],answer:0,explain:"AI merespons apa yang kamu tulis. Pertanyaan yang jelas & berkonteks menghasilkan jawaban yang lebih berguna.",hint:"Apakah pertanyaan samar atau jelas menghasilkan jawaban lebih tepat?"},
{n:2,type:"mcq",micro:"Memberi konteks",q:"Manakah permintaan yang kemungkinan menghasilkan jawaban paling berguna?",options:["'Jelaskan fotosintesis.'","'Aku murid kelas 6. Jelaskan fotosintesis dalam 4 kalimat sederhana dengan satu contoh sehari-hari.'","'fotosintesis'"],answer:1,explain:"Menyebut siapa kamu, seberapa panjang, tingkat kesulitan, & format membuat jawaban jauh lebih pas.",hint:"Detail apa yang membantu AI menyesuaikan jawaban untukmu?"},
{n:3,type:"mcq",micro:"Menyatakan tujuan",q:"Menyebutkan UNTUK APA kamu butuh jawabannya ('untuk presentasi', 'untuk memahami sebelum ulangan') membantu karena...",options:["Tidak berpengaruh","Membuat jawaban lebih pendek saja","AI bisa menyesuaikan kedalaman, gaya, & fokus jawaban dengan keperluanmu"],answer:2,explain:"Tujuan yang berbeda butuh jawaban yang berbeda. Menyatakannya mengarahkan AI.",hint:"Apakah jawaban 'untuk presentasi 3 menit' sama dengan 'untuk esai 5 halaman'?"},
{n:4,type:"mcq",micro:"Meminta format tertentu",q:"Kamu bisa meminta jawaban dalam bentuk...",options:["Daftar poin, tabel, langkah demi langkah, ringkasan singkat, atau paragraf — sebutkan yang kamu inginkan","Hanya dalam bentuk paragraf panjang saja, karena AI tidak bisa membuat daftar, tabel, atau ringkasan singkat","Format jawaban tidak bisa diminta sama sekali, karena AI selalu memilih sendiri bentuk jawabannya tanpa bisa diatur"],answer:0,explain:"Menyebut format yang diinginkan membuat jawaban lebih mudah dipakai.",hint:"Bentuk apa yang paling membantumu: daftar, tabel, atau paragraf?"},
{n:5,type:"mcq",micro:"Memeriksa jawaban penting",q:"Setelah AI memberi jawaban yang akan kamu pakai untuk tugas atau keputusan, langkah wajib:",options:["Percaya karena terdengar meyakinkan","Periksa fakta kuncinya dengan sumber tepercaya yang independen","Salin langsung"],answer:1,explain:"AI bisa keliru dengan meyakinkan (halusinasi). Verifikasi melindungi kamu dari kesalahan.",hint:"Apakah 'terdengar benar' sama dengan 'benar'?"},
{n:6,type:"order",micro:"Alur memakai AI untuk sebuah pertanyaan",q:"Urutkan langkah memakai AI dengan bijak untuk menjawab sebuah pertanyaan tugas.",items:["Perjelas apa yang kamu butuhkan & apa yang sudah kamu ketahui","Tulis pertanyaan yang jelas dengan konteks (siapa kamu, tujuan, format)","Baca jawaban dengan kritis; minta klarifikasi atau perbaikan bila perlu","Verifikasi fakta penting dengan sumber lain sebelum memakainya"],answer:[0,1,2,3],explain:"Perjelas kebutuhan → tanya dengan konteks → tinjau kritis → verifikasi.",hint:"Kamu perlu tahu apa yang kamu cari sebelum bisa bertanya dengan baik."},
{n:7,type:"mcq",micro:"Iterasi",q:"Kalau jawaban pertama AI kurang pas, cara yang baik:",options:["Menyerah","Menyalin apa adanya","Beri umpan balik spesifik: 'terlalu panjang, buat 3 poin', 'terlalu sulit, pakai bahasa lebih sederhana', 'fokus ke bagian X'"],answer:2,explain:"Percakapan dengan AI bersifat iteratif. Umpan balik spesifik memperbaiki jawaban berikutnya.",hint:"Bagaimana kamu memberi tahu apa yang kurang dari jawaban pertama?"},
{n:8,type:"mcq",micro:"AI untuk memahami, bukan menyontek",q:"Cara memakai AI yang membantu pembelajaran:",options:["Minta ia menjelaskan langkah/konsep yang kamu bingungkan, lalu kerjakan sendiri; bukan minta jawaban jadi untuk disalin","Minta jawaban semua soal sekaligus lalu salin langsung ke buku tanpa dibaca atau dipahami caranya sedikit pun","Tidak pernah memakai AI sama sekali untuk belajar, karena setiap penjelasan dari AI pasti keliru dan menyesatkan"],answer:0,explain:"AI sebagai tutor memperkuat pemahaman; AI sebagai pengganti usaha mengikis keterampilan.",hint:"Apa bedanya 'jelaskan mengapa langkah ini begini' dengan 'beri jawaban akhir'?"},
{n:9,type:"mcq",micro:"Jangan berbagi data sensitif",q:"Sebelum mengetik informasi ke layanan AI, hindari memasukkan...",options:["Permintaan untuk menuliskan sebuah puisi pendek tentang hujan yang tidak memuat data pribadi siapa pun","Kata sandi, nomor identitas, data kesehatan pribadi, alamat rumah, atau rahasia orang lain","Pertanyaan umum tentang pelajaran di sekolah yang jawabannya ada di buku pelajaran dan tidak bersifat rahasia"],answer:1,explain:"Data yang kamu masukkan bisa disimpan atau dipakai lebih lanjut. Jangan bagikan informasi sensitif ke layanan yang tidak jelas kebijakannya.",hint:"Bagaimana perasaanmu kalau apa yang kamu ketik bisa dilihat orang lain nanti?"},
{n:10,type:"mcq",micro:"AI tidak tahu segalanya",q:"Kalau kamu bertanya tentang kejadian yang sangat baru atau informasi yang sangat lokal, AI...",options:["Selalu tahu jawaban terbarunya dengan tepat, karena AI terhubung langsung ke semua kejadian yang baru terjadi","Tidak pernah salah soal fakta lokal, karena AI mengenal setiap daerah, desa, dan toko di seluruh dunia dengan teliti","Mungkin tidak tahu atau memberi info usang/keliru — cek dengan sumber terkini"],answer:2,explain:"Pengetahuan model terbatas pada data pelatihannya. Untuk hal baru atau spesifik lokal, verifikasi wajib.",hint:"Kalau 'buku pelajaran' AI dicetak tahun lalu, apakah ia tahu berita minggu ini?"},
{n:11,type:"tf",micro:"Jawaban yang lancar belum tentu benar",q:"Benar atau Salah: AI bisa memberi jawaban yang sangat lancar, percaya diri, & terperinci namun tetap keliru isinya.",answer:true,explain:"Kelancaran & kebenaran adalah hal berbeda. Model dilatih menghasilkan teks yang terdengar wajar, jadi bisa fasih sekaligus salah.",hint:"Apakah 'terdengar pintar' sama dengan 'benar'?"},
{n:12,type:"mcq",micro:"Meminta AI menunjukkan langkah",q:"Untuk soal matematika/logika, meminta AI 'tunjukkan langkah-langkahnya' berguna karena...",options:["Kamu bisa memeriksa penalarannya & belajar caranya, bukan hanya menerima angka akhir","Membuat jawaban jadi lebih panjang saja tanpa manfaat apa pun bagi orang yang sedang berusaha memahami soalnya","Langkah-langkah tidak penting, yang terpenting hanya angka akhirnya, jadi kamu cukup menyalin hasil tanpa memeriksa caranya"],answer:0,explain:"Melihat langkah memungkinkan kamu menemukan di mana AI (atau kamu) keliru, & memahami metodenya.",hint:"Bagaimana kamu tahu jawaban akhir benar tanpa melihat caranya?"},
{n:13,type:"mcq",micro:"Bertanya ulang dengan cara berbeda",q:"Kalau kamu ragu sebuah jawaban benar, salah satu pemeriksaan cepat:",options:["Tanyakan sepuluh kali dengan kalimat yang persis sama, lalu anggap jawaban yang paling sering muncul pasti benar","Tanyakan hal yang sama dengan kata-kata berbeda, atau minta AI memeriksa/mengkritik jawabannya sendiri — lalu bandingkan","Percaya jawaban pertama saja karena AI selalu paling tepat pada percobaan pertama dan tidak perlu dicek atau dibandingkan lagi"],answer:1,explain:"Jawaban yang tidak konsisten saat ditanya ulang adalah tanda perlu verifikasi eksternal.",hint:"Apakah jawaban AI selalu sama kalau kamu tanya dengan cara berbeda?"},
{n:14,type:"tf",micro:"Kamu bertanggung jawab atas hasilnya",q:"Benar atau Salah: Kalau kamu memakai AI untuk membantu tugas lalu menyerahkannya & ada kesalahan di dalamnya, AI-lah yang bertanggung jawab, bukan kamu.",answer:false,explain:"AI adalah alat bantu. Orang yang memakai & menyerahkan hasil tetap bertanggung jawab memverifikasi & memahaminya — nama kamu yang tertera pada tugas itu.",hint:"Nama siapa yang tertera pada tugas itu?"},
{n:15,type:"mcq",micro:"Kejujuran & pengungkapan",q:"Kalau guru bertanya apakah kamu memakai bantuan AI untuk sebuah tugas, sikap yang jujur:",options:["Selalu menyangkal","Tidak perlu dijawab","Sampaikan apa adanya bagaimana kamu memakainya (mis. 'untuk memahami konsep', 'untuk memeriksa tata bahasa') sesuai aturan yang berlaku"],answer:2,explain:"Kejujuran tentang penggunaan alat adalah bagian dari integritas. Ikuti aturan sekolah tentang apa yang boleh & bagaimana mengungkapkannya.",hint:"Apa yang akan kamu rasakan kalau ketahuan menyembunyikannya?"},
{n:16,type:"mcq",micro:"AI untuk brainstorming",q:"Salah satu pemakaian AI yang aman & berguna:",options:["Menghasilkan banyak ide awal untuk sebuah proyek, yang lalu kamu saring, kembangkan, & pilih sendiri","Menentukan keputusan penting dalam hidupmu, seperti memilih sekolah lanjutan, tanpa kamu memikirkannya sama sekali sendiri","Menggantikan seluruh proses berpikirmu, sehingga kamu cukup menyalin hasilnya dan tidak perlu menyaring atau mengembangkan apa pun"],answer:0,explain:"AI bagus untuk memperluas pilihan di awal. Penyaringan, pengembangan, & keputusan tetap milikmu.",hint:"Untuk apa AI berguna di tahap 'mengumpulkan banyak kemungkinan'?"},
{n:17,type:"mcq",micro:"Meminta sumber",q:"Kalau AI menyebut fakta, kamu bisa meminta 'sebutkan dari mana informasi ini' — tapi ingat...",options:["Tidak perlu sumber","Sumber yang disebut AI kadang keliru atau tidak ada; tetap cek langsung ke sumber aslinya","Sumber dari AI selalu akurat"],answer:1,explain:"AI bisa 'mengarang' rujukan yang terdengar meyakinkan. Selalu periksa apakah sumbernya nyata & benar-benar mendukung klaimnya.",hint:"Apakah nama buku yang disebut AI pasti ada?"},
{n:18,type:"mcq",micro:"Kapan AI cukup, kapan tidak",q:"Untuk 'menerjemahkan menu makanan di negara asing', AI...",options:["Tidak boleh dipakai","Harus diverifikasi penerjemah resmi","Umumnya cukup — taruhan rendah, mudah dicek kalau ragu"],answer:2,explain:"Kecocokan pemakaian bergantung taruhan. Keperluan santai berisiko rendah menoleransi kesalahan kecil.",hint:"Apa akibat terburuk kalau terjemahan menu sedikit meleset?"},
{n:19,type:"mcq",micro:"Menyimpan pikiran kritis",q:"Memiliki akses ke AI seharusnya membuat kamu...",options:["Lebih terlatih memeriksa fakta & menilai argumen, karena AI bisa keliru dengan meyakinkan","Berhenti memeriksa apa pun, karena dengan AI semua informasi pasti sudah benar dan tidak perlu dicek lagi oleh siapa pun","Percaya semua yang dikatakan AI, karena ia terdengar yakin dan pintar sehingga tidak mungkin memberi jawaban yang keliru"],answer:0,explain:"Alat yang kadang salah menuntut pengguna yang lebih kritis, bukan kurang.",hint:"Kalau alatmu kadang salah, apakah kamu jadi lebih atau kurang butuh menilai sendiri?"},
{n:20,type:"open",micro:"Menulis pertanyaan yang baik",q:"Kamu butuh bantuan AI untuk memahami 'bagaimana gunung berapi meletus' untuk tugas IPA kelas 7. Tulis SATU pertanyaan/instruksi yang jelas & berkonteks (sebutkan tingkatmu, tujuan, panjang, format, & apa yang sudah kamu tahu), lalu tuliskan 2 hal yang akan kamu verifikasi dari jawabannya.",explain:"Jawaban baik menunjukkan pertanyaan dengan konteks lengkap (tingkat, tujuan, panjang, format, pengetahuan awal) & rencana verifikasi yang menyasar fakta spesifik.",hint:"Semakin spesifik konteksmu, semakin pas jawabannya — & rencanakan mengecek angka & urutan.",sample:"Pertanyaan: 'Aku murid kelas 7 dan sedang membuat poster IPA. Jelaskan bagaimana gunung berapi meletus dalam 5 langkah berurutan, dengan bahasa sederhana dan satu istilah kunci per langkah (dicetak tebal). Aku sudah tahu bahwa magma berasal dari dalam bumi, tapi tidak paham apa yang membuatnya naik ke permukaan.' Verifikasi: (1) apakah urutan langkah & istilah (magma, tekanan gas, ruang magma, dsb.) cocok dengan buku IPA / situs lembaga sains tepercaya; (2) apakah ada penyederhanaan yang keliru (mis. klaim angka suhu/kedalaman) — cek angkanya."},
{n:21,type:"mcq",micro:"Memecah permintaan besar",q:"Untuk tugas besar ('bantu aku menulis makalah'), pendekatan yang lebih baik:",options:["Jangan pakai AI sama sekali untuk tugas besar apa pun, sebab satu-satunya cara jujur adalah mengerjakan semuanya tanpa bantuan","Pecah jadi langkah: bantu susun kerangka → bahas satu bagian → beri masukan pada tulisanku — bukan minta seluruh makalah sekaligus","Minta makalah lengkap sekaligus lalu serahkan langsung kepada guru tanpa dibaca, diubah, atau dipahami isinya terlebih dahulu"],answer:1,explain:"Memakai AI langkah demi langkah menjaga kamu tetap penulis & pemikir utamanya, sekaligus dapat bantuan di titik yang tepat.",hint:"Bagaimana memakai AI tanpa menjadikannya penulis sebenarnya?"},
{n:22,type:"mcq",micro:"Meminta AI menantang idemu",q:"Setelah kamu menulis argumen, meminta AI 'sebutkan kelemahan terkuat argumen ini & sudut pandang yang berlawanan' berguna untuk...",options:["Membuat kamu ragu tanpa manfaat","Menghapus argumenmu","Menemukan celah sebelum orang lain, & memperkuat tulisanmu"],answer:2,explain:"AI sebagai 'penantang' membantu berpikir kritis — kamu tetap yang memutuskan bagaimana merespons kritik itu.",hint:"Siapa yang lebih baik menemukan kelemahan tulisanmu: pemuji atau penantang?"},
{n:23,type:"classify",micro:"Pemakaian AI: sesuai, sesuai-dengan-syarat, atau tidak",q:"Kelompokkan tiap pemakaian: 'Sesuai (aman)', 'Sesuai dengan verifikasi/pengungkapan', atau 'Tidak sesuai'.",items:["Meminta AI menjelaskan konsep yang membingungkan lalu kamu kerjakan sendiri","Meminta AI menulis seluruh esai lomba lalu menyerahkannya sebagai karya orisinalmu","Meminta AI membuat draf pertanyaan wawancara yang lalu kamu edit & sesuaikan"],groups:["Sesuai (aman)","Sesuai dengan verifikasi/pengungkapan","Tidak sesuai"],answer:{"Sesuai (aman)":["Meminta AI menjelaskan konsep yang membingungkan lalu kamu kerjakan sendiri"],"Sesuai dengan verifikasi/pengungkapan":["Meminta AI membuat draf pertanyaan wawancara yang lalu kamu edit & sesuaikan"],"Tidak sesuai":["Meminta AI menulis seluruh esai lomba lalu menyerahkannya sebagai karya orisinalmu"]},explain:"Belajar & memahami = aman; draf yang kamu kerjakan lanjut = perlu diungkapkan sesuai aturan; mengklaim karya AI sebagai orisinal di konteks yang menilai orisinalitas = tidak jujur.",hint:"Apakah kamu tetap penulis/pemikirnya? Apakah orisinalitas yang dinilai?"},
{n:24,type:"mcq",micro:"Memberi contoh yang kamu inginkan",q:"Kalau kamu ingin AI menulis dengan gaya tertentu, cara yang efektif:",options:["Beri satu-dua contoh gaya yang kamu maksud, lalu minta ia mengikuti pola itu","Berharap ia menebak gayamu sendiri tanpa diberi contoh atau petunjuk apa pun tentang gaya penulisan yang kamu inginkan","Tidak mungkin mengatur gaya tulisan AI, karena ia selalu menulis dengan satu gaya yang sama untuk semua orang dan semua tugas"],answer:0,explain:"Menunjukkan contoh ('seperti ini: ...') sering lebih efektif daripada mendeskripsikan gaya dengan kata-kata.",hint:"Lebih mudah menjelaskan gaya lewat deskripsi atau lewat contoh?"},
{n:25,type:"mcq",micro:"Percakapan mengingat konteks",q:"Dalam satu percakapan, AI biasanya 'ingat' apa yang kamu katakan sebelumnya. Manfaatnya:",options:["Kamu harus mengulang semuanya tiap pesan","Kamu bisa membangun bertahap ('sekarang perpendek', 'tambahkan contoh') tanpa mengulang semua konteks tiap kali","Tidak ada manfaat"],answer:1,explain:"Percakapan berlapis memungkinkan penyempurnaan bertahap. (Percakapan baru biasanya mulai dari nol.)",hint:"Perlukah kamu menjelaskan ulang tugasmu di setiap pesan dalam satu percakapan?"},
{n:26,type:"mcq",micro:"Batas ingatan percakapan",q:"Kalau percakapan jadi sangat panjang, AI bisa...",options:["Selalu ingat semuanya tanpa batas","Berhenti bekerja","Mulai 'melupakan' detail dari awal percakapan — ringkas kembali poin penting bila perlu"],answer:2,explain:"Ada batas berapa banyak konteks yang bisa dipegang model. Untuk percakapan panjang, mengulang poin kunci membantu.",hint:"Apa yang bisa terjadi pada instruksi di pesan pertama setelah 50 pesan?"},
{n:27,type:"mcq",micro:"Meminta beberapa pilihan",q:"Untuk keputusan kreatif (judul, tema, pendekatan), meminta AI 'beri 5 opsi berbeda' lebih baik daripada meminta 1 karena...",options:["Kamu punya bahan untuk membandingkan & memilih, & bisa menggabungkan bagian dari beberapa","Satu opsi selalu cukup karena AI pasti memberi yang terbaik pada jawaban pertama, sehingga tidak perlu ada pilihan lain","Lima opsi hanya membingungkan dan membuang waktu, sebab keputusan kreatif sebaiknya tidak pernah dibandingkan atau dipilih manusia"],answer:0,explain:"AI berguna untuk memperluas ruang pilihan; kamu yang menyaring & memutuskan.",hint:"Apakah lebih mudah memilih dari 1 pilihan atau dari beberapa?"},
{n:28,type:"tf",micro:"Verifikasi sesuai taruhan",q:"Benar atau Salah: Semua jawaban AI harus diverifikasi dengan tingkat ketelitian yang persis sama, tidak peduli seberapa besar akibatnya kalau jawaban itu salah.",answer:false,explain:"Ketelitian verifikasi sebaiknya sepadan dengan taruhannya: untuk hal sepele & mudah dibatalkan, cek ringan cukup; untuk tugas dinilai, keputusan, atau info yang akan disebarkan, verifikasi ketat.",hint:"Apakah terjemahan menu & laporan sains butuh tingkat pengecekan yang sama?"},
{n:29,type:"mcq",micro:"AI & tugas yang butuh angka presisi",q:"Untuk perhitungan panjang yang harus tepat, cara yang lebih andal:",options:["Menebak","Pakai kalkulator/program hitung, atau minta AI menuliskan rumus & langkahnya lalu kamu hitung/cek sendiri","Percaya angka akhir dari AI langsung"],answer:1,explain:"Model bahasa memprediksi teks, bukan menghitung. Untuk presisi, pakai alat hitung atau verifikasi manual.",hint:"Alat mana yang tugas utamanya memang berhitung?"},
{n:30,type:"order",micro:"Menyempurnakan jawaban lewat percakapan",q:"Urutkan langkah menyempurnakan jawaban AI yang belum pas.",items:["Baca jawaban & identifikasi persis apa yang kurang (terlalu panjang? salah fokus? terlalu sulit?)","Beri instruksi perbaikan yang spesifik","Baca versi baru & ulangi bila perlu","Setelah cukup baik, verifikasi fakta pentingnya sebelum memakai"],answer:[0,1,2,3],explain:"Identifikasi kekurangan → instruksi spesifik → tinjau ulang → verifikasi.",hint:"Kamu perlu tahu apa yang kurang sebelum bisa memintanya diperbaiki."},
{n:31,type:"mcq",micro:"AI untuk belajar bahasa",q:"Cara memakai AI yang membantu belajar bahasa asing:",options:["Menyalin terjemahan dari AI begitu saja ke tugas tanpa berusaha memahami arti kata, tata bahasa, atau cara pemakaiannya","Hanya memakainya untuk menyontek saat ujian bahasa, karena itu satu-satunya manfaat AI dalam belajar bahasa asing yang ada","Berlatih percakapan, minta koreksi kalimatmu dengan penjelasan, tanya perbedaan kata mirip — sambil tetap belajar dari sumber terstruktur"],answer:2,explain:"AI bisa jadi mitra latihan yang sabar. Verifikasi hal yang meragukan & jangan andalkan sepenuhnya untuk tata bahasa halus.",hint:"Bagaimana AI membantumu BERLATIH, bukan sekadar memberi jawaban?"},
{n:32,type:"mcq",micro:"Menyadari jawaban yang bervariasi",q:"Kamu bertanya hal yang sama di dua percakapan & mendapat jawaban berbeda. Ini...",options:["Normal — model sering menambah sedikit keacakan; kalau jawabannya soal fakta, cari kepastian dari sumber lain","Berarti salah satu percakapan itu rusak, dan hanya jawaban dari percakapan yang pertama saja yang boleh dipercaya","Tidak mungkin terjadi sama sekali, sebab AI selalu memberi jawaban yang persis sama untuk pertanyaan yang sama kapan pun ditanya"],answer:0,explain:"Variasi keluaran adalah sifat model generatif. Untuk fakta, jangan bergantung pada satu jawaban.",hint:"Apakah AI selalu memberi jawaban yang identik?"},
{n:33,type:"mcq",micro:"AI & tugas kelompok",q:"Dalam tugas kelompok, memakai AI secara sehat berarti...",options:["Sembunyikan pemakaian AI dari anggota kelompok lain supaya tidak ada yang bertanya atau menuntut pembagian tugas yang adil","Sepakati bersama untuk apa AI dipakai (mis. cek tata bahasa, brainstorming) & pastikan setiap anggota tetap memahami & berkontribusi pada isinya","Satu orang saja yang meminta AI mengerjakan semuanya, lalu anggota lain cukup menyerahkan hasilnya tanpa membaca atau memahaminya"],answer:1,explain:"Kesepakatan tim & pemahaman bersama menjaga integritas & pembelajaran semua anggota.",hint:"Bagaimana memastikan semua anggota tetap belajar & tugas tetap karya kelompok?"},
{n:34,type:"mcq",micro:"Meminta penjelasan bertingkat",q:"Kalau jawaban AI terlalu sulit, kamu bisa minta...",options:["Jawaban yang lebih rumit","Berhenti bertanya","'Jelaskan seperti ke anak 10 tahun', atau 'jelaskan lagi dengan analogi sehari-hari'"],answer:2,explain:"AI bisa menyesuaikan tingkat penjelasan. Meminta versi lebih sederhana atau beranalogi sering membuka pemahaman.",hint:"Apa yang kamu katakan kalau penjelasan pertama di atas kepalamu?"},
{n:35,type:"mcq",micro:"Menghindari plagiarisme",q:"Kalau kamu memakai ide atau kalimat dari jawaban AI dalam tulisanmu, praktik yang jujur:",options:["Tulis dengan pemahaman & kata-katamu sendiri, & ikuti aturan sekolah tentang pengungkapan pemakaian AI","Salin persis kalimat AI ke tulisanmu tanpa menyebut apa pun, karena kalimat yang bagus tidak perlu diberi keterangan sumbernya","Ubah beberapa kata saja lalu klaim seluruh tulisan sebagai karyamu sendiri sepenuhnya, tanpa mengikuti aturan sekolah apa pun"],answer:0,explain:"Menyerahkan tulisan yang sebenarnya bukan hasil pemikiran & kata-katamu sebagai karya orisinal adalah bentuk ketidakjujuran.",hint:"Apakah tulisan itu benar-benar mencerminkan pemahaman & suaramu sendiri?"},
{n:36,type:"tf",micro:"AI bisa membantu memeriksa pekerjaanmu",q:"Benar atau Salah: Meminta AI meninjau tulisan atau jawabanmu (tata bahasa, kejelasan, kelemahan argumen) bisa berguna, asal kamu tetap yang memutuskan perubahan mana yang diterapkan.",answer:true,explain:"AI sebagai pemberi masukan bisa membantu — tapi kamu menilai apakah masukannya tepat & tetap memegang kendali atas karyamu.",hint:"Siapa yang memutuskan apakah saran perbaikan itu bagus?"},
{n:37,type:"mcq",micro:"Ketika AI menolak atau tidak bisa",q:"Kalau AI menolak membantu atau bilang tidak yakin, respons yang tepat:",options:["Anggap AI rusak","Hormati batas itu; cari cara lain (sumber lain, bertanya guru) — jangan mencoba 'mengakali' agar ia melakukan hal yang tidak semestinya","Terus memaksa dengan berbagai trik"],answer:1,explain:"Batas & ketidakpastian yang dinyatakan AI sering ada alasannya. Menghormatinya & mencari jalur lain lebih bijak.",hint:"Kalau AI bilang 'aku tidak yakin soal ini', apa yang sebaiknya kamu lakukan?"},
{n:38,type:"mcq",micro:"Menyaring, bukan menelan",q:"Setelah AI memberi daftar panjang saran/ide, langkah yang baik:",options:["Pakai semuanya tanpa memilih","Buang semuanya","Baca kritis, buang yang tidak relevan/tidak realistis, pilih & kembangkan yang cocok dengan situasi & nilaimu"],answer:2,explain:"AI memperluas pilihan; penyaringan berdasarkan konteks & penilaianmu adalah bagian yang tidak bisa didelegasikan.",hint:"Apakah semua ide dari AI cocok untuk situasimu?"},
{n:39,type:"mcq",micro:"Menyadari batas pengetahuanmu sendiri",q:"Bahaya memakai AI untuk topik yang kamu sama sekali tidak paham:",options:["Kamu tidak bisa mengenali kalau jawabannya keliru — verifikasi jadi lebih penting, & bangun pemahaman dasar dari sumber tepercaya dulu","Tidak ada bahaya","AI selalu benar untuk topik asing"],answer:0,explain:"Kemampuanmu menilai jawaban AI bergantung pada pengetahuanmu. Untuk topik yang sangat asing, pemeriksaan eksternal & belajar dasar wajib.",hint:"Bisakah kamu tahu jawaban itu salah kalau kamu tidak tahu apa-apa tentang topiknya?"},
{n:40,type:"open",micro:"Merancang percakapan AI yang produktif",q:"Kamu ingin bantuan AI untuk memperbaiki paragraf pembuka esaimu tentang pentingnya membaca. Tuliskan urutan 3–4 pesan yang akan kamu kirim (dengan konteks & instruksi spesifik tiap pesan), & jelaskan bagaimana kamu menjaga esai itu tetap karyamu sendiri.",explain:"Jawaban baik menunjukkan pemakaian AI sebagai pemberi masukan & inspirasi (bukan penulis), dengan instruksi eksplisit 'jangan tulis ulang untukku', & penulis tetap mengerjakan & memahami revisinya.",hint:"Minta masukan & inspirasi, bukan kalimat jadi — & selalu tulis versi finalnya sendiri.",sample:"Pesan 1: 'Aku murid kelas 8 menulis esai persuasif tentang pentingnya membaca untuk lomba menulis. Ini paragraf pembukaku: [tempel paragraf]. Beri masukan tentang kejelasan & daya tariknya, tapi JANGAN menulis ulang untukku — cukup tunjukkan 2-3 hal yang bisa diperbaiki & mengapa.' Pesan 2 (setelah masukan): 'Poin tentang kalimat pertama yang kurang menarik — beri aku 3 contoh JENIS pembuka yang berbeda (pertanyaan, kutipan, cerita singkat) sebagai inspirasi, bukan untuk kusalin.' Pesan 3 (setelah aku menulis ulang sendiri): 'Ini versi baruku: [tempel]. Apakah lebih jelas? Ada kesalahan tata bahasa?' Menjaga karya tetap milikku: aku menulis & menulis ulang sendiri; AI hanya memberi masukan & inspirasi jenis pembuka, bukan kalimat jadi; aku memahami setiap perubahan yang kubuat & bisa menjelaskannya."},
{n:41,type:"mcq",micro:"Anatomi instruksi yang efektif",q:"Instruksi AI yang efektif sering memuat: peran/konteks kamu, tugas yang jelas, batasan (panjang/gaya/tingkat), format keluaran, dan...",options:["Nama lengkapmu","Apa yang sudah kamu ketahui atau contoh yang kamu inginkan","Waktu & tanggal"],answer:1,explain:"Menyebut pengetahuan awal atau contoh membantu AI menyesuaikan & menghindari mengulang hal yang sudah kamu pahami.",hint:"Apa lagi selain 'tugas & format' yang membuat jawaban lebih pas?"},
{n:42,type:"mcq",micro:"Verifikasi silang",q:"Cara paling kuat memverifikasi klaim faktual dari AI:",options:["Tanya AI yang sama sekali lagi dengan kalimat yang agak berbeda, lalu anggap pasti benar kalau jawabannya sama saja","Percaya saja kalau jawabannya terdengar meyakinkan dan ditulis dengan rapi, sebab jawaban keliru biasanya terdengar ragu-ragu","Cek di 2+ sumber tepercaya yang independen (buku, situs lembaga resmi, ensiklopedia terkurasi) — bukan hanya bertanya ke AI lain"],answer:2,explain:"Konfirmasi dari sumber independen yang tepercaya jauh lebih kuat daripada menanyakan ulang model yang sama.",hint:"Apakah bertanya ke AI yang sama dua kali memberi bukti independen?"},
{n:43,type:"mcq",micro:"Tanda jawaban perlu verifikasi ekstra",q:"Jawaban AI paling perlu diperiksa ketat bila mengandung...",options:["Angka spesifik, tanggal, kutipan, nama, statistik, atau klaim tentang kejadian terkini/lokal","Definisi konsep umum yang mapan dan dikenal luas, seperti arti kata 'segitiga' yang tercantum di semua buku pelajaran","Saran umum tentang cara belajar yang baik, seperti perlunya tidur cukup dan mengulang pelajaran secara teratur di rumah"],answer:0,explain:"Detail presisi & hal terkini paling rawan keliru (halusinasi). Konsep umum yang mapan lebih andal.",hint:"Mana yang lebih mungkin 'dikarang': konsep umum, atau angka statistik persis?"},
{n:44,type:"mcq",micro:"Memilih apakah AI cocok untuk tugas",q:"Sebelum memakai AI untuk sebuah tugas, tanyakan: apakah tugas ini terutama tentang...",options:["Tidak pernah cocok untuk tugas apa pun juga, karena AI hanyalah mesin yang tidak bisa membantu pekerjaan manusia sama sekali, baik untuk menyusun, menjelaskan, maupun menghasilkan sesuatu berbasis pola","Menghasilkan/menyusun/menjelaskan sesuatu berbasis pola (cocok) — atau tentang penilaian nilai, tanggung jawab, atau data pribadi yang harus dijaga (hati-hati/tidak)","Selalu cocok untuk semua tugas tanpa kecuali, termasuk yang menyangkut data pribadi, penilaian nilai, dan tanggung jawab manusia, sehingga tidak perlu berhati-hati atau memikirkannya lebih dulu"],answer:1,explain:"AI kuat untuk tugas berpola (draf, penjelasan, ringkasan, ide); lemah/tidak tepat untuk keputusan moral, tanggung jawab, & hal sensitif.",hint:"Apakah tugas ini butuh 'menyusun teks/ide' atau 'memutuskan yang benar untuk seseorang'?"},
{n:45,type:"mcq",micro:"Prompt untuk pemahaman mendalam",q:"Untuk benar-benar memahami sebuah konsep (bukan sekadar mendapat definisi), kamu bisa minta AI...",options:["Memberi definisi satu kalimat saja lalu berhenti, supaya kamu bisa langsung menghafalnya tanpa perlu contoh atau latihan","Memberi jawaban untuk semua soal PR-mu sekaligus, sehingga kamu merasa paham padahal belum pernah mencoba mengerjakannya sendiri","Menjelaskan, memberi analogi, memberi contoh & non-contoh, lalu menanyai kamu soal latihan untuk mengecek pemahamanmu"],answer:2,explain:"Memakai AI sebagai tutor aktif (menjelaskan + menguji kamu) membangun pemahaman jauh lebih baik daripada sekadar menerima jawaban.",hint:"Bagaimana AI bisa membantumu MENGUJI apakah kamu sudah paham?"},
{n:46,type:"mcq",micro:"Menghindari 'jangkar' pada jawaban pertama",q:"Kalau kamu menanyakan pendapat/analisis, risiko menerima jawaban pertama AI apa adanya:",options:["Kamu bisa 'terjangkar' pada framing AI & berhenti berpikir sendiri — coba bentuk pendapatmu dulu, lalu bandingkan dengan AI","Tidak ada risiko","Jawaban pertama selalu terbaik"],answer:0,explain:"Membentuk pandanganmu sendiri sebelum melihat jawaban AI menjaga kemandirian berpikirmu.",hint:"Apa yang terjadi pada pemikiranmu kalau kamu selalu melihat jawaban AI dulu?"},
{n:47,type:"order",micro:"Alur memakai AI untuk riset topik baru",q:"Urutkan langkah memakai AI untuk mulai meriset topik yang asing bagimu.",items:["Minta AI memberi gambaran umum & istilah kunci topik itu","Bangun pemahaman dasar dari sumber tepercaya (buku/ensiklopedia/situs lembaga) memakai istilah tadi","Kembali ke AI dengan pertanyaan yang lebih spesifik & tajam","Verifikasi setiap fakta/angka yang akan kamu pakai dengan sumber independen"],answer:[0,1,2,3],explain:"Gambaran umum & istilah → bangun dasar dari sumber tepercaya → pertanyaan spesifik → verifikasi.",hint:"AI bagus untuk 'peta awal'; pemahaman & verifikasi butuh sumber tepercaya."},
{n:48,type:"mcq",micro:"Membedakan opini & fakta dalam jawaban AI",q:"Jawaban AI bisa mencampur fakta (bisa diverifikasi) dengan penilaian/opini (bergantung nilai). Sikap yang baik:",options:["Perlakukan semuanya sebagai opini belaka, termasuk tanggal dan angka yang sebenarnya bisa dicek kebenarannya di sumber tepercaya","Pisahkan keduanya: verifikasi bagian faktual; perlakukan bagian penilaian sebagai satu sudut pandang yang bisa kamu setujui atau tidak","Perlakukan semuanya sebagai fakta yang pasti benar, termasuk penilaian dan pendapat yang sebenarnya bergantung pada nilai seseorang"],answer:1,explain:"Membedakan 'apa yang benar' dari 'apa yang sebaiknya' membantu memakai jawaban AI dengan tepat.",hint:"Bagian mana yang bisa dicek benar/salah, & bagian mana yang soal nilai?"},
{n:49,type:"mcq",micro:"Menyesuaikan tingkat ketergantungan",q:"Untuk tugas yang menilai keterampilanmu (menulis, memecahkan soal), tingkat ketergantungan AI yang sehat:",options:["Tinggi — biarkan AI mengerjakan semuanya, lalu kamu tinggal menyerahkan hasilnya tanpa berlatih apa pun yang dinilai itu","Nol — AI dilarang total untuk semua keperluan, bahkan sekadar untuk memahami contoh atau memeriksa pekerjaan yang sudah kamu tulis","Rendah — pakai untuk memahami & memeriksa, kerjakan inti sendiri, agar kamu benar-benar berlatih & bisa saat AI tidak ada"],answer:2,explain:"Semakin sebuah tugas dimaksudkan melatih keterampilanmu, semakin sedikit sebaiknya AI menggantikan usahamu.",hint:"Apa tujuan sebenarnya dari tugas menulis — teks yang bagus, atau kemampuan menulismu?"},
{n:50,type:"mcq",micro:"Mengecek bias dalam jawaban",q:"Jawaban AI tentang topik yang punya banyak sudut pandang bisa...",options:["Condong ke pandangan yang paling umum di data pelatihannya — minta ia menyajikan beberapa sudut pandang, & cari sumber dari perspektif berbeda","Selalu netral dengan sempurna, karena AI tidak punya sudut pandang dan datanya mewakili semua pendapat dengan porsi yang sama","Selalu menyajikan semua sisi secara adil tanpa perlu diminta, sehingga kamu tidak perlu mencari sumber dari sudut pandang lain"],answer:0,explain:"Model mencerminkan pola dalam data pelatihannya, yang bisa berat sebelah. Sengaja meminta beragam sudut pandang membantu.",hint:"Apakah 'jawaban paling umum' sama dengan 'jawaban paling adil ke semua pihak'?"},
{n:51,type:"open",micro:"Rencana verifikasi",q:"AI memberimu jawaban ini untuk tugas: 'Terumbu karang menutupi kurang dari 1% dasar laut tapi menjadi rumah bagi sekitar 25% spesies laut. Kenaikan suhu laut 1-2°C dapat menyebabkan pemutihan karang massal.' Buat rencana verifikasi: (1) klaim mana yang perlu dicek, (2) sumber seperti apa yang kamu pakai, (3) apa yang kamu lakukan kalau sumber berbeda-beda, (4) bagaimana kamu menuliskannya di tugasmu.",explain:"Jawaban baik mengidentifikasi klaim numerik/spesifik sebagai yang perlu dicek, memilih sumber tepercaya (bukan AI/blog), menangani ketidaksepakatan sumber dengan jujur, & mengutip sumber asli (bukan AI).",hint:"Angka spesifik selalu masuk daftar 'perlu dicek'; kutip sumber asli, bukan AI.",sample:"(1) Klaim yang dicek: angka '<1% dasar laut', '25% spesies laut', & '1-2°C menyebabkan pemutihan massal' — ketiganya angka/klaim spesifik yang rawan keliru. (2) Sumber: situs lembaga kelautan/lingkungan resmi (mis. lembaga sains pemerintah, badan PBB terkait, ensiklopedia sains terkurasi), atau buku pelajaran biologi terbaru — bukan blog acak. (3) Kalau sumber berbeda (mis. satu bilang 25%, lain bilang 'lebih dari sepertiga'): tulis rentang atau perkiraan ('sekitar seperempat hingga sepertiga') & sebutkan bahwa angkanya bervariasi antar sumber; utamakan sumber paling tepercaya & terbaru. (4) Di tugasku: tulis dengan kata-kataku sendiri, cantumkan sumber yang kupakai (bukan 'menurut AI'), & bila diminta, sebutkan bahwa aku memakai AI untuk gambaran awal lalu memverifikasi ke sumber X & Y."},
{n:52,type:"mcq",micro:"Menyusun ulang, bukan menyalin",q:"Setelah AI menjelaskan sesuatu & kamu memahaminya, cara memasukkannya ke tugas dengan jujur & efektif:",options:["Salin persis","Tutup jawaban AI, lalu tulis penjelasannya dengan kata-katamu sendiri dari pemahaman — jauh lebih menempel di ingatan & benar-benar karyamu","Salin-tempel & ubah beberapa sinonim"],answer:1,explain:"Menulis ulang dari pemahaman (bukan dari teks di depan mata) menguji & memperkuat pemahamanmu, & menghasilkan tulisan yang benar-benar milikmu.",hint:"Kapan kamu benar-benar tahu kamu paham sesuatu — saat bisa menyalinnya, atau saat bisa menjelaskannya tanpa melihat?"},
{n:53,type:"tf",micro:"AI yang berbeda bisa memberi jawaban berbeda",q:"Benar atau Salah: Semua alat AI pada dasarnya program yang sama, jadi untuk pertanyaan yang sama mereka akan selalu memberi jawaban yang identik.",answer:false,explain:"Alat AI yang berbeda (atau versi berbeda) dilatih & disetel secara berbeda, jadi bisa memberi jawaban berbeda untuk pertanyaan yang sama. Jangan anggap 'AI bilang' sebagai satu suara tunggal.",hint:"Apakah semua alat AI adalah program yang sama persis?"},
{n:54,type:"mcq",micro:"Memakai AI untuk umpan balik, bukan penilaian akhir",q:"Kamu memakai AI untuk menilai kualitas jawaban temanmu (dengan izinnya). Sikap yang tepat:",options:["Terima skor dari AI sebagai nilai final dan tidak perlu ditinjau, karena mesin menilai lebih adil daripada guru atau pihak berwenang","AI tidak boleh dipakai untuk apa pun yang berkaitan dengan penilaian, bahkan sebagai satu bahan pertimbangan tambahan bagi orang yang berwenang","Perlakukan penilaian AI sebagai satu masukan; keputusan akhir & tanggung jawab menilai tetap pada manusia yang berwenang"],answer:2,explain:"AI bisa memberi umpan balik cepat, tapi penilaian yang berdampak (nilai, kelulusan) butuh penilaian & tanggung jawab manusia.",hint:"Siapa yang bertanggung jawab kalau penilaian itu keliru & merugikan seseorang?"},
{n:55,type:"mcq",micro:"Menyimpan jejak pemikiran sendiri",q:"Kebiasaan yang menjaga kemandirian berpikir saat sering memakai AI:",options:["Tuliskan dulu pemikiran/jawaban awalmu sendiri sebelum bertanya ke AI, lalu bandingkan & pelajari perbedaannya","Selalu tanya AI lebih dulu sebelum kamu berpikir sendiri, supaya jawabanmu cepat selesai dan pasti sama dengan jawaban yang benar","Tidak pernah menuliskan apa pun sendiri, karena membandingkan pikiranmu dengan jawaban AI hanya membuang waktu dan tidak ada gunanya"],answer:0,explain:"Membentuk jawaban sendiri dulu menjaga otot berpikirmu tetap terlatih & membuat kamu bisa mengevaluasi jawaban AI, bukan sekadar menerimanya.",hint:"Apa yang menjaga kamu tetap berpikir aktif, bukan pasif menerima?"},
{n:56,type:"mcq",micro:"Waktu yang dihemat vs waktu yang hilang",q:"AI bisa menghemat waktu, tapi juga bisa membuang waktu bila...",options:["Kamu memakainya untuk hal-hal sepele yang sebenarnya bisa dikerjakan dalam beberapa detik, walaupun hasilnya selalu tepat dan cepat, sehingga tidak ada kekacauan yang perlu diperbaiki sesudahnya","Kamu terus meminta variasi jawaban tanpa memutuskan, atau memverifikasi jawaban yang seharusnya kamu tahu sendiri, atau memperbaiki kekacauan dari jawaban yang salah dipercaya","AI tidak pernah membuang waktu siapa pun, sebab setiap jawabannya selalu langsung benar sehingga tidak ada yang perlu diulang, dicek, atau diperbaiki, dan variasi jawaban tidak pernah menyita waktu"],answer:1,explain:"Pemakaian yang bijak menimbang: apakah AI benar-benar mempercepat, atau menambah langkah (verifikasi, revisi kesalahan)?",hint:"Kapan memakai AI justru lebih lambat daripada mengerjakan sendiri?"},
{n:57,type:"tf",micro:"Prompt yang jelas adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Menulis instruksi yang jelas & efektif untuk AI adalah keterampilan yang membaik dengan latihan & memperhatikan pola apa yang menghasilkan jawaban baik.",answer:true,explain:"Seperti keterampilan lain, 'bertanya dengan baik' berkembang: kamu belajar memberi konteks, format, & batasan yang tepat.",hint:"Apakah orang menjadi lebih baik menulis pertanyaan setelah banyak berlatih?"},
{n:58,type:"mcq",micro:"Kapan berhenti bertanya ke AI",q:"Tanda kamu sebaiknya berhenti bertanya ke AI & beralih ke sumber lain atau orang:",options:["AI selalu bisa menjawab semuanya dengan benar dan konsisten, bahkan untuk topik terkini dan taruhan tinggi, jadi tidak perlu berhenti","Tidak pernah ada alasan berhenti — selalu tanya AI saja untuk semua hal, termasuk yang membutuhkan tanggung jawab dan konteks manusia","Jawaban terus berputar/tidak konsisten, topiknya terlalu terkini/spesifik, taruhannya tinggi, atau kamu butuh tanggung jawab & konteks manusia"],answer:2,explain:"Mengenali batas AI & tahu kapan beralih (ke buku, ahli, guru) adalah bagian dari memakainya dengan bijak.",hint:"Kapan kamu butuh manusia sungguhan, bukan alat?"},
{n:59,type:"mcq",micro:"Etika: karya lomba & orisinalitas",q:"Menyerahkan karya (esai, gambar, lagu) yang sebagian besar dibuat AI ke lomba yang menilai kreativitas & orisinalitas peserta...",options:["Adalah ketidakjujuran — konteks itu menilai kemampuan & ekspresi peserta sendiri","Boleh saja asal tidak ketahuan oleh juri, sebab yang penting karyanya bagus dan kamu bisa memenangkan hadiahnya dengan mudah","Selalu boleh dalam lomba apa pun karena AI hanyalah alat, sehingga siapa pun bisa mengaku sebagai penciptanya tanpa masalah"],answer:0,explain:"Di konteks yang inti-nya menilai orisinalitas & kemampuan orangnya, mengaku-aku karya AI sebagai buatan sendiri melanggar aturan main.",hint:"Apa yang sebenarnya dinilai lomba itu — hasil akhir, atau kemampuan pesertanya?"},
{n:60,type:"open",micro:"Panduan pemakaian AI untuk tugas sekolah",q:"Tulis panduan pribadi 'Cara Aku Memakai AI untuk Tugas Sekolah' dengan minimal 6 aturan. Cakup: untuk apa AI boleh dipakai, untuk apa tidak, cara verifikasi, cara menjaga karya tetap milikmu, kejujuran/pengungkapan, & menjaga keterampilan. Beri alasan tiap aturan.",explain:"Panduan baik memisahkan pemakaian yang membantu belajar dari yang menggantikan usaha, menetapkan verifikasi & kutipan sumber asli, menjaga kepenulisan & pemahaman, mengatur kejujuran, & melindungi keterampilan + data — dengan alasan tiap aturan.",hint:"Untuk tiap aturan, tanyakan: apakah ini membantuku BELAJAR & tetap jujur, atau menggantikan yang seharusnya kukerjakan?",sample:"(1) AI boleh untuk: menjelaskan konsep yang kubingungkan, memberi contoh, brainstorming ide, & memeriksa tata bahasa/kejelasan tulisanku — karena ini membantu belajar, bukan menggantikan usaha. (2) AI TIDAK untuk: menulis esai/jawaban lengkap yang kuserahkan sebagai karyaku, atau mengerjakan soal latihan tanpa aku mencoba — karena itu menghilangkan latihan yang kubutuhkan & tidak jujur. (3) Setiap fakta/angka dari AI yang masuk tugasku kuverifikasi di minimal 1 sumber tepercaya (buku/situs lembaga), & kukutip sumber ASLI, bukan 'menurut AI' — karena AI bisa mengarang detail. (4) Aku selalu menulis versi final dengan kata-kataku sendiri dari pemahaman, bukan menyalin — karena begitu aku benar-benar belajar & tulisannya jadi milikku. (5) Kalau guru bertanya atau aturan meminta, aku ungkapkan bagaimana aku memakai AI (mis. 'untuk memahami & cek tata bahasa') — karena kejujuran bagian dari integritas. (6) Untuk soal yang menilai keterampilanku (matematika, menulis), aku coba sendiri dulu sampai mentok baru minta penjelasan langkah — supaya aku siap saat ujian tanpa AI. (7) Aku tidak memasukkan data pribadi (nama lengkap keluarga, alamat, foto) ke layanan AI."},
{n:61,type:"mcq",micro:"Ketergantungan yang mengikis kemampuan",q:"Kalau kamu selalu memakai AI untuk merangkum bacaan & tidak pernah membaca sendiri, seiring waktu...",options:["Kemampuan membacamu otomatis meningkat","Kemampuanmu membaca teks panjang, menangkap ide utama, & menahan fokus bisa melemah — keterampilan tumbuh dari latihan","Tidak ada efek"],answer:1,explain:"Menyerahkan proses berpikir yang seharusnya melatihmu bisa membuat keterampilan itu tidak berkembang atau menurun.",hint:"Apa yang terjadi pada otot yang tidak pernah dipakai?"},
{n:62,type:"mcq",micro:"AI yang setuju denganmu",q:"AI sering cenderung 'ramah' & setuju dengan framing pertanyaanmu. Kalau kamu bertanya 'kenapa X itu benar', ia mungkin...",options:["Selalu memberi pandangan yang seimbang","Menolak menjawab","Memberi argumen untuk X tanpa cukup menantangnya — sengaja minta 'argumen terkuat MELAWAN X' untuk keseimbangan"],answer:2,explain:"Cara kamu membingkai pertanyaan memengaruhi jawaban. Untuk analisis jujur, minta juga sisi yang berlawanan.",hint:"Kalau kamu bertanya 'kenapa aku benar', jawaban apa yang mungkin kamu dapat?"},
{n:63,type:"tf",micro:"Jawaban yang detail bukan jaminan akurat",q:"Benar atau Salah: Jawaban AI yang panjang, terperinci, & penuh angka bisa terasa lebih meyakinkan padahal justru lebih berisiko mengandung detail yang keliru.",answer:true,explain:"Semakin banyak detail spesifik, semakin banyak titik yang bisa salah. Kepercayaan diri penyajian tidak berkorelasi dengan akurasi.",hint:"Mana yang punya lebih banyak 'titik yang bisa keliru': jawaban singkat umum, atau jawaban penuh angka spesifik?"},
{n:64,type:"mcq",micro:"Memakai AI untuk keputusan pribadi",q:"Untuk keputusan pribadi besar (memilih minat, menghadapi konflik dengan teman), AI...",options:["Bisa membantu memetakan pilihan & pertimbangan, tapi keputusan & tanggung jawabnya milikmu — & AI tidak mengenal seluruh konteks hidupmu","Sebaiknya yang memutuskan untukmu sepenuhnya, karena AI lebih tahu tentang hidup dan perasaanmu daripada dirimu sendiri dan orang terdekatmu","Tidak berguna sama sekali untuk keputusan pribadi apa pun, bahkan sekadar membantu menuliskan pilihan dan pertimbangan yang kamu miliki"],answer:0,explain:"AI bisa jadi alat berpikir, tapi keputusan hidup butuh konteks, nilai, & tanggung jawab yang hanya kamu miliki.",hint:"Apakah AI tahu seluruh cerita hidupmu & apa yang benar-benar kamu pedulikan?"},
{n:65,type:"mcq",micro:"Verifikasi yang malas",q:"'Verifikasi' dengan hanya bertanya ke AI 'apakah jawabanmu tadi benar?'...",options:["Cara terbaik memverifikasi","Lemah — model bisa saja membenarkan diri; verifikasi nyata butuh sumber independen di luar model","Cukup & efisien"],answer:1,explain:"Menanyakan model tentang kebenaran jawabannya sendiri bukan pemeriksaan independen.",hint:"Apakah bertanya ke orang yang sama 'apakah kamu yakin?' membuktikan sesuatu?"},
{n:66,type:"tf",micro:"Konteks yang kamu berikan tetap di layanan itu",q:"Benar atau Salah: Apa pun yang kamu ketik ke layanan AI selalu sepenuhnya privat, tidak pernah disimpan, ditinjau orang, atau dipakai untuk melatih model.",answer:false,explain:"Kebijakan tiap layanan berbeda, tapi asumsi aman: apa yang kamu ketik bisa disimpan, ditinjau, atau dipakai melatih model — jadi berhati-hati dengan info sensitif tetap penting.",hint:"Ke mana perginya apa yang kamu ketik ke sebuah layanan daring?"},
{n:67,type:"mcq",micro:"Menyeimbangkan bantuan & kejujuran akademik",q:"Aturan sekolah tentang AI berbeda-beda. Sikap yang bertanggung jawab:",options:["Anggap semua pemakaian boleh dilakukan dalam tugas apa pun, karena sekolah pasti tidak keberatan dengan teknologi yang sedang populer","Anggap semua pemakaian dilarang dan sembunyikan saja bila kamu memakainya, supaya tidak ada guru yang bertanya atau menegurmu","Cari tahu & ikuti aturan spesifik kelas/tugasmu; kalau ragu, tanya guru sebelum memakai — bukan berasumsi"],answer:2,explain:"Aturan berbeda antar guru & tugas. Bertanya lebih dulu menghindari pelanggaran yang tidak disengaja & menunjukkan itikad baik.",hint:"Apa cara paling aman untuk tahu apa yang boleh?"},
{n:68,type:"mcq",micro:"Jawaban yang 'cukup baik' vs benar",q:"AI memberi jawaban yang terdengar masuk akal & kamu tidak punya cara mudah mengeceknya. Untuk tugas yang dinilai:",options:["Jangan pakai bagian yang tidak bisa kamu verifikasi; cari sumber yang bisa dipastikan, atau nyatakan ketidakpastian dengan jujur","Pakai saja bagian itu karena terdengar benar dan masuk akal, jadi tidak perlu repot mencari tahu apakah buktinya ada","Pakai lalu berharap tidak ketahuan kalau ternyata keliru, sebab guru jarang memeriksa isi tugas dengan teliti satu per satu"],answer:0,explain:"Memasukkan klaim yang tidak bisa kamu pastikan berisiko menyebarkan kesalahan & merusak kredibilitas tugasmu.",hint:"Apa yang lebih baik: klaim yang mungkin salah, atau mengakui 'ini belum bisa kupastikan'?"},
{n:69,type:"mcq",micro:"AI & kreativitas",q:"Memakai AI untuk menghasilkan ide bisa membantu, tapi risikonya bila tidak hati-hati:",options:["AI tidak berpengaruh sama sekali pada kreativitas seseorang, sebab ide dari mesin dan ide dari manusia selalu sama saja nilainya, dan tidak ada risiko ide-idemu menjadi seragam dengan orang lain","Ide-idemu bisa jadi seragam dengan ide orang lain yang bertanya serupa, & kamu berhenti mengasah imajinasi sendiri — pakai AI sebagai pemantik, lalu kembangkan ke arah yang khas kamu","Kreativitasmu otomatis meningkat setiap kali memakai AI, tanpa perlu kamu mengembangkan atau mengubah ide-ide yang diberikannya sedikit pun, dan imajinasimu tidak mungkin berhenti terasah"],answer:1,explain:"AI menyodorkan ide 'rata-rata' dari polanya. Kekhasan & kedalaman datang dari pengembangan & pilihan pribadimu.",hint:"Kalau semua orang minta ide ke AI yang sama, seberapa unik hasilnya?"},
{n:70,type:"order",micro:"Menangani jawaban AI yang kamu curigai salah",q:"Urutkan langkah saat kamu curiga jawaban AI keliru.",items:["Kenali bagian mana persisnya yang kamu ragukan & mengapa","Cek bagian itu di sumber tepercaya yang independen","Kalau sumber bertentangan dengan AI, percayai sumber tepercaya & perbaiki","Kalau masih tidak jelas, cari lebih banyak sumber atau tanya orang yang ahli"],answer:[0,1,2,3],explain:"Tunjuk keraguannya → cek sumber independen → percayai sumber tepercaya → gali lebih jauh bila perlu.",hint:"Sebelum mengecek, perjelas apa persisnya yang kamu ragukan."},
{n:71,type:"mcq",micro:"Menjaga suara sendiri dalam tulisan",q:"Kalau tulisanmu yang dibantu AI terasa 'bukan seperti kamu', itu tanda...",options:["Tulisan yang bagus memang tidak punya suara pribadi sama sekali, jadi rasa 'bukan seperti kamu' itu tanda tulisannya sudah sempurna","Tidak masalah sama sekali selama tulisannya rapi dan enak dibaca, sebab gaya, contoh, dan sudut pandang pribadi tidak penting dalam tulisan","Kamu mungkin terlalu mengandalkan kalimat AI — tulis ulang dengan gaya, contoh, & sudut pandangmu sendiri agar terasa autentik"],answer:2,explain:"Tulisan yang baik punya suara. Kalau AI mendominasi, hasilnya terasa generik & bukan milikmu.",hint:"Apakah tulisan itu terdengar seperti kamu berbicara?"},
{n:72,type:"mcq",micro:"AI untuk topik sensitif/pribadi",q:"Untuk hal yang menyangkut kesehatan mental, hubungan sulit, atau keputusan berat, AI...",options:["Bisa memberi informasi umum, tapi untuk dukungan nyata cari orang tepercaya (keluarga, guru BK, profesional) — & jangan bagikan detail sangat pribadi ke layanan yang tidak jelas","Adalah pengganti terbaik bagi konselor dan orang dewasa tepercaya, sehingga kamu tidak perlu lagi bercerita kepada keluarga, guru BK, atau profesional, dan boleh membagikan semua detail pribadimu","Harus menjadi satu-satunya tempat kamu bercerita tentang semua masalah pribadimu, termasuk detail yang sangat rahasia dan sensitif, serta tidak perlu mencari orang tepercaya di sekitarmu"],answer:0,explain:"AI tidak punya tanggung jawab, konteks penuh, atau kemampuan menjaga kerahasiaan seperti profesional. Untuk hal berat, manusia tepercaya penting.",hint:"Siapa yang bisa benar-benar mendukungmu & bertanggung jawab menjaga kepercayaanmu?"},
{n:73,type:"tf",micro:"Memakai AI dengan baik butuh pengetahuan & penilaian",q:"Benar atau Salah: Memakai AI secara efektif & aman justru menuntut pengetahuan & keterampilan berpikir yang cukup — orang yang tahu lebih banyak bisa mengarahkan & mengevaluasi AI dengan lebih baik.",answer:true,explain:"AI memperkuat orang yang sudah punya dasar. Ia bukan pengganti belajar; ia alat yang paling berguna di tangan yang terlatih.",hint:"Siapa yang bisa menilai jawaban AI dengan lebih baik: yang paham topiknya atau yang tidak?"},
{n:74,type:"mcq",micro:"Prompt yang mengarahkan ke jawaban keliru",q:"Kalau kamu bertanya dengan premis yang salah ('jelaskan kenapa bumi datar'), AI yang baik seharusnya...",options:["Menolak semua pertanyaan yang memuat kata-kata aneh, tanpa menjelaskan apa yang salah dari premis dalam pertanyaanmu itu","Mengoreksi premisnya, bukan sekadar menuruti — tapi tidak semua model konsisten melakukannya, jadi tetap waspada pada premismu sendiri","Selalu menuruti apa pun premisnya, karena tugas AI hanyalah menjawab dan tidak pernah menilai benar atau salahnya pertanyaan"],answer:1,explain:"Pertanyaan berpremis salah bisa menghasilkan jawaban menyesatkan. Periksa apakah premismu sendiri sudah benar.",hint:"Apakah AI selalu membetulkan kesalahan dalam pertanyaanmu?"},
{n:75,type:"mcq",micro:"Menimbang biaya lingkungan & sumber daya",q:"Menjalankan model AI besar butuh energi & sumber daya. Implikasi untuk pemakaian bijak:",options:["Pakai sebanyak mungkin","Jangan pernah pakai","Pakai seperlunya & tepat guna — untuk hal yang benar-benar dibantu AI — bukan untuk setiap hal sepele yang bisa kamu lakukan sendiri dengan cepat"],answer:2,explain:"Seperti sumber daya lain, pemakaian yang sadar & tepat guna lebih baik daripada berlebihan tanpa tujuan.",hint:"Apakah kamu butuh AI untuk menjawab '2+2' atau menerjemahkan satu kata yang kamu tahu?"},
{n:76,type:"mcq",micro:"Menyikapi jawaban yang tidak kamu suka",q:"AI memberi jawaban yang bertentangan dengan yang kamu harapkan. Sikap yang matang:",options:["Periksa apakah jawaban itu didukung bukti (verifikasi); kalau ya, pertimbangkan bahwa kamu mungkin perlu memperbarui pandanganmu — bukan langsung menolak karena tidak sesuai harapan","Tolak jawaban itu dan tanya terus sampai AI memberi jawaban yang kamu inginkan, tanpa memeriksa bukti yang mendukungnya, karena pandanganmu sendiri pasti benar dan tidak perlu diperbarui","Terima langsung tanpa dicek, karena AI pasti lebih tahu daripada dirimu sehingga pandanganmu harus segera diganti dengannya, walaupun kamu belum memeriksa apakah ada bukti yang mendukungnya"],answer:0,explain:"Baik menerima maupun menolak jawaban harus berdasarkan bukti, bukan apakah jawaban itu menyenangkan.",hint:"Apakah kamu menolak jawaban karena salah, atau karena tidak kamu suka?"},
{n:77,type:"tf",micro:"AI adalah alat, bukan otoritas",q:"Benar atau Salah: Jawaban AI sebaiknya diperlakukan sebagai vonis dari otoritas yang tidak bisa salah, bukan sekadar masukan dari alat yang bisa keliru.",answer:false,explain:"Memberi AI status 'otoritas' membuat kita berhenti berpikir kritis. Ia alat: berguna, tapi perlu diarahkan & diperiksa — perlakukan jawabannya sebagai masukan yang bisa keliru.",hint:"Apakah kamu memperlakukan kalkulator sebagai 'otoritas' atau sebagai 'alat'?"},
{n:78,type:"mcq",micro:"Membangun kebiasaan verifikasi",q:"Cara membuat verifikasi jadi kebiasaan, bukan beban:",options:["Percaya saja pada semua jawaban AI untuk menghemat waktu, sehingga tidak ada lagi aturan yang perlu diingat atau dijalankan","Tetapkan aturan sederhana untuk diri sendiri (mis. 'setiap angka/nama/tanggal dari AI dicek sebelum dipakai') & jadikan otomatis","Lakukan verifikasi hanya kalau sedang sempat dan tidak sibuk, sedangkan kalau terburu-buru langsung pakai saja jawabannya"],answer:1,explain:"Aturan pribadi yang jelas & konsisten mengubah verifikasi dari keputusan berulang menjadi kebiasaan otomatis.",hint:"Apa aturan singkat yang bisa kamu jadikan refleks?"},
{n:79,type:"mcq",micro:"Mengajari orang lain memakai AI dengan bijak",q:"Membantu teman/keluarga memakai AI dengan bijak paling efektif dengan mengajarkan...",options:["Trik-trik untuk mendapatkan jawaban tercepat saja, tanpa membahas verifikasi, privasi, atau kemungkinan AI memberi jawaban yang keliru","Bahwa AI selalu benar dalam semua jawabannya, sehingga mereka cukup menyalin tanpa perlu berpikir, memeriksa, atau bertanya lagi","Prinsip: beri konteks yang jelas, verifikasi hal penting, jangan bagikan data sensitif, & ingat AI bisa keliru — bukan hanya trik pintar"],answer:2,explain:"Prinsip yang bisa dipindahkan (konteks, verifikasi, privasi, skeptisisme sehat) lebih berharga daripada trik spesifik.",hint:"Apa yang berguna di banyak situasi: satu trik, atau pemahaman prinsip?"},
{n:80,type:"open",micro:"Menganalisis pemakaian AI yang bermasalah",q:"Seorang siswa bercerita: 'Aku selalu minta AI mengerjakan semua PR-ku, menyalin jawabannya, dan nilaiku bagus. Tapi saat ulangan di kelas aku tidak bisa apa-apa.' Analisis: (1) apa yang salah dengan pendekatannya, (2) apa yang mungkin ia rasa sebagai 'manfaat', (3) apa akibat jangka panjangnya, (4) rancang cara memakai AI yang akan membantunya benar-benar belajar untuk topik yang sama.",explain:"Jawaban baik mengenali bahwa PR bertujuan melatih (bukan menghasilkan jawaban), menjelaskan rantai akibat (keterampilan tidak terbangun → gagal ujian), & merancang pemakaian AI sebagai tutor (menjelaskan + membuat latihan + menandai kelemahan) alih-alih pengganti usaha.",hint:"Apa TUJUAN sebenarnya dari PR — jawaban yang benar di kertas, atau kemampuan yang teruji saat ulangan?",sample:"(1) Ia memakai AI sebagai PENGGANTI usaha, bukan alat belajar — menyalin jawaban tanpa memahami berarti proses berlatih (yang sebenarnya tujuan PR) tidak pernah terjadi. Ini juga tidak jujur bila PR dinilai sebagai karyanya. (2) 'Manfaat' yang ia rasa: PR selesai cepat, nilai PR bagus, tidak perlu berjuang. (3) Akibat jangka panjang: keterampilan tidak terbangun → gagal di ulangan/ujian tanpa AI; kepercayaan diri jatuh; kebiasaan menghindari kesulitan; bila ketahuan, konsekuensi integritas; & di masa depan, kesulitan pada hal yang butuh keterampilan itu. (4) Cara yang membantu belajar: kerjakan tiap soal sendiri dulu sampai mentok; untuk yang tidak bisa, minta AI MENJELASKAN langkah & konsepnya (bukan jawaban), lalu tutup & kerjakan ulang sendiri; minta AI membuat 3 soal SERUPA untuk latihan tambahan & cek jawabanku dengan penjelasan; sebelum ulangan, kerjakan soal-soal itu tanpa AI & minta AI menandai mana yang masih lemah. Dengan cara ini nilai PR mungkin turun sementara, tapi kemampuan (yang diuji ulangan) benar-benar naik."},
{n:81,type:"mcq",micro:"Memilih tingkat bantuan AI untuk berbagai tugas",q:"Prinsip umum memilih seberapa banyak mengandalkan AI:",options:["Semakin tugas dimaksudkan melatih keterampilanmu atau semakin besar taruhan/tanggung jawabnya, semakin sedikit AI menggantikan usahamu — & semakin ketat verifikasinya","Selalu andalkan sepenuhnya","Selalu tolak total"],answer:0,explain:"Kalibrasi: bantuan draf/penjelasan untuk hal rutin & taruhan rendah; usaha & penilaian sendiri untuk hal yang melatihmu atau berdampak besar.",hint:"Dua faktor: apakah ini melatihku? seberapa besar akibatnya kalau keliru?"},
{n:82,type:"mcq",micro:"Menyusun instruksi kompleks",q:"Untuk tugas rumit, instruksi AI yang baik bisa disusun berlapis:",options:["Ajukan sebanyak mungkin pertanyaan sekaligus dalam satu pesan panjang tanpa struktur, lalu berharap AI mengerti mana yang paling kamu butuhkan, tanpa menyebut konteks, batasan, format, atau contoh apa pun","Konteks & tujuan → tugas spesifik → batasan (panjang/gaya/tingkat) → format → apa yang HARUS & TIDAK BOLEH dilakukan (mis. 'jangan menulis ulang, beri masukan saja') → contoh bila ada","Cukup satu kata kunci saja tanpa konteks, tujuan, batasan, atau format, karena AI sudah pasti paham semua maksud dari kata itu, dan tidak perlu diberi tahu apa yang harus dan tidak boleh dilakukan"],answer:1,explain:"Instruksi yang terstruktur & menyebut batasan (termasuk apa yang tidak boleh dilakukan) menghasilkan bantuan yang tepat sasaran.",hint:"Apa yang membuat AI membantu dengan cara yang persis kamu inginkan?"},
{n:83,type:"tf",micro:"Verifikasi & pemahaman tidak bisa didelegasikan",q:"Benar atau Salah: Kamu bisa mendelegasikan penyusunan draf ke AI, tapi memverifikasi kebenaran & benar-benar memahami isi tetap harus kamu lakukan sendiri bila kamu yang bertanggung jawab atas hasilnya.",answer:true,explain:"Tanggung jawab atas kebenaran & pemahaman melekat pada orang yang memakai & menyerahkan hasil, tidak bisa dipindahkan ke alat.",hint:"Kalau AI salah & kamu yang menyerahkan, siapa yang menanggung akibatnya?"},
{n:84,type:"mcq",micro:"Menilai apakah AI membuatmu lebih baik",q:"Pertanyaan refleksi berkala tentang pemakaian AI-mu:",options:["'Berapa banyak waktu yang berhasil kuhemat dengan AI hari ini?' saja, tanpa perlu memikirkan apakah keterampilanku ikut berkembang","Tidak perlu refleksi sama sekali, sebab selama tugasnya selesai dan nilainya bagus, cara memakai AI tidak perlu dipertanyakan lagi","'Apakah AI membantuku BELAJAR & bekerja lebih baik, atau aku jadi bergantung & keterampilanku menurun? Apakah aku masih bisa melakukannya tanpa AI?'"],answer:2,explain:"Ukuran pemakaian yang sehat bukan hanya kecepatan, tapi apakah kamu tumbuh atau menyusut sebagai pembelajar & pekerja.",hint:"Bagaimana kamu tahu AI membantumu berkembang, bukan mengikis kemampuanmu?"},
{n:85,type:"order",micro:"Memakai AI untuk proyek penulisan besar dengan jujur & efektif",q:"Urutkan langkah memakai AI untuk membantu esai panjang tanpa kehilangan kepenulisan.",items:["Bentuk gagasan & posisimu sendiri lebih dulu; tulis kerangka kasar","Pakai AI untuk memeriksa kerangka (celah logika, sudut pandang lawan yang terlewat) & untuk menjelaskan konsep yang kubingungkan","Tulis draf dengan kata-kata & suaraku sendiri; verifikasi setiap fakta yang kupakai","Minta AI masukan pada kejelasan & tata bahasa draf-ku; putuskan sendiri perubahan mana yang kuterapkan; ungkapkan pemakaian AI sesuai aturan"],answer:[0,1,2,3],explain:"Gagasan sendiri dulu → AI untuk memeriksa & menjelaskan → tulis & verifikasi sendiri → AI untuk poles, kamu memutuskan, lalu ungkapkan.",hint:"Penulisnya tetap kamu; AI membantu di pinggiran (memeriksa, menjelaskan, memoles)."},
{n:86,type:"mcq",micro:"Menyikapi jawaban AI tentang dirinya sendiri",q:"Kamu bertanya ke AI 'apakah kamu bisa keliru?' & ia menjawab 'ya, saya bisa keliru, verifikasilah'. Sikap yang tepat:",options:["Terima itu sebagai pengingat yang benar & terapkan — perlakukan semua jawabannya sebagai perlu diverifikasi untuk hal penting","Anggap ia hanya merendah saja, karena sebenarnya jawabannya pasti benar dan peringatan itu tidak perlu dianggap serius oleh siapa pun","Berhenti memakainya sama sekali mulai sekarang, karena alat yang mengaku bisa keliru berarti tidak berguna untuk keperluan apa pun"],answer:0,explain:"Pengakuan model bahwa ia bisa keliru sejalan dengan cara kerjanya. Itu bukan basa-basi — perlakukan sebagai panduan nyata.",hint:"Kalau alat itu sendiri bilang 'aku kadang salah', apa yang bijak kamu lakukan?"},
{n:87,type:"mcq",micro:"AI & keputusan yang memengaruhi orang lain",q:"Kamu ketua kelas & mempertimbangkan memakai AI untuk menyusun daftar 'siapa yang layak jadi ketua kelompok'. Sikap yang tepat:",options:["AI tidak boleh dipakai untuk apa pun di kelas, bahkan untuk hal administratif sederhana seperti mengingatkan jadwal atau mengatur piket","Jangan serahkan penilaian tentang orang ke AI; kalaupun AI dipakai untuk hal administratif, keputusan tentang orang harus lewat proses yang adil & tanggung jawab manusia","Pakai saja daftar dari AI sebagai keputusan final, karena mesin pasti lebih objektif dan tidak akan membuat teman-teman merasa dibeda-bedakan"],answer:1,explain:"Keputusan yang menilai & memengaruhi orang lain butuh keadilan, konteks, & tanggung jawab yang tidak bisa didelegasikan ke pola statistik.",hint:"Bagaimana perasaan temanmu kalau tahu 'kelayakan' mereka dinilai oleh sebuah program?"},
{n:88,type:"tf",micro:"Pemakaian bijak = manfaat maksimal, risiko minimal",q:"Benar atau Salah: Memakai AI dengan bijak berarti memakainya sebanyak mungkin untuk segala hal, tanpa perlu memikirkan risiko seperti kesalahan tak terverifikasi atau kehilangan keterampilan.",answer:false,explain:"Pemakaian bijak bukan 'pakai sebanyak mungkin' atau 'jangan pakai sama sekali', melainkan menyeimbangkan manfaat (belajar lebih cepat, ide lebih banyak) & risiko (kesalahan tak terverifikasi, kehilangan keterampilan, kebocoran data, ketidakjujuran) secara sadar.",hint:"Apa dua sisi yang perlu diseimbangkan?"},
{n:89,type:"mcq",micro:"Membedakan bantuan yang memberdayakan & yang melumpuhkan",q:"Bantuan AI yang MEMBERDAYAKAN vs yang MELUMPUHKAN, contohnya:",options:["Keduanya sama","Semua bantuan AI memberdayakan","Memberdayakan: menjelaskan konsep sampai kamu bisa menerapkannya sendiri. Melumpuhkan: memberi jawaban jadi sehingga kamu tidak pernah belajar menerapkannya"],answer:2,explain:"Bantuan yang baik meninggalkan kamu lebih mampu; bantuan yang buruk meninggalkan kamu bergantung.",hint:"Setelah bantuan itu, apakah kamu lebih bisa melakukannya sendiri, atau kurang?"},
{n:90,type:"mcq",micro:"Menyusun kebijakan AI untuk sebuah kelompok",q:"Kelompok belajarmu ingin sepakat soal pemakaian AI. Isi yang penting dalam kesepakatan:",options:["Untuk apa AI boleh/tidak dipakai bersama, kewajiban verifikasi & memahami, kejujuran soal kontribusi, & bahwa setiap anggota tetap harus bisa menjelaskan bagian yang jadi tanggung jawabnya","Bahwa satu orang boleh meminta AI mengerjakan semuanya, lalu anggota lain cukup menyetujui hasilnya tanpa perlu membaca atau memahaminya, dan pemakaian AI sebaiknya disembunyikan dari guru maupun anggota lain","Bahwa AI dilarang total tanpa pengecualian apa pun, bahkan untuk memeriksa tata bahasa atau menjelaskan konsep yang belum dipahami anggota, dan siapa pun yang melanggarnya harus dikeluarkan dari kelompok"],answer:0,explain:"Kesepakatan yang baik memperjelas pemakaian yang membantu, menjaga verifikasi & pemahaman, & memastikan kontribusi & pertanggungjawaban tiap anggota.",hint:"Bagaimana memastikan AI membantu kelompok belajar, bukan menggantikan belajarnya?"},
{n:91,type:"tf",micro:"Keterampilan memakai AI melengkapi, bukan menggantikan, keterampilan dasar",q:"Benar atau Salah: Kalau kamu sudah mahir memakai AI, kamu tidak lagi perlu keterampilan dasar seperti membaca kritis, menulis, berhitung, atau menalar.",answer:false,explain:"Justru sebaliknya: kemahiran memakai AI paling berharga bila dibangun DI ATAS keterampilan dasar yang kuat. Tanpa dasar, kamu tidak bisa mengarahkan atau mengevaluasi AI & mudah tersesat oleh kesalahannya.",hint:"Bisakah kamu menilai jawaban AI tentang sejarah kalau kamu tidak bisa membaca kritis?"},
{n:92,type:"mcq",micro:"Menyikapi perkembangan AI yang cepat",q:"Karena alat AI cepat berubah, sikap yang tahan lama:",options:["Tunggu sampai AI 'selesai' berkembang dan alatnya sudah stabil, baru kemudian mulai belajar cara memakainya dengan benar dan bijak","Pegang prinsipnya (beri konteks, verifikasi, jaga data, ingat AI bisa keliru, jaga keterampilan & kejujuran) — prinsip ini tetap berlaku meski alatnya berganti","Hafalkan trik-trik khusus untuk satu alat tertentu saja, karena trik itu pasti akan tetap berguna walaupun alatnya berubah atau diganti"],answer:1,explain:"Trik spesifik cepat usang; prinsip pemakaian yang bijak bertahan lintas alat & versi.",hint:"Apa yang tetap berguna meski alatnya berganti tiap tahun?"},
{n:93,type:"mcq",micro:"Ringkasan: menggunakan AI dengan bijak",q:"Rangkuman paling tepat:",options:["Percaya semua jawaban AI dan serahkan semua tugas kepadanya, sebab alat itu pasti lebih cepat, lebih pintar, dan lebih jujur daripada kamu sendiri sebagai pelajar, sehingga tidak perlu memberi konteks, memverifikasi, menjaga data pribadi, atau mengikuti aturan sekolah, sehingga kamu tidak perlu menjaga keterampilan dasar, tidak perlu jujur soal bantuan yang diterima, dan tidak perlu menjadi penulis atau pemikir utama dalam tugasmu sendiri","Jangan pernah memakai AI untuk apa pun dalam keadaan apa pun, karena semua pemakaiannya pasti curang, berbahaya, dan hanya membuat kemampuan berpikir manusia hilang, sehingga tidak ada gunanya mempelajari cara memberi instruksi, memverifikasi jawaban, atau menjaga privasi dengan baik dan hanya orang yang tidak memahami teknologi yang masih mau belajar menulis, berhitung, atau menalar sendiri tanpa bantuan mesin yang sempurna itu","Beri konteks & instruksi yang jelas; perlakukan jawaban sebagai tebakan alat yang bisa keliru; verifikasi hal penting dengan sumber independen sepadan taruhannya; jaga data pribadi; pakai untuk memahami & memeriksa (bukan menggantikan usaha yang melatihmu); tetap yang bertanggung jawab & penulis/pemikir utamanya; jujur & ikuti aturan; & bangun keterampilan ini di atas keterampilan dasar yang kuat"],answer:2,explain:"Pemakaian bijak = instruksi jelas + skeptisisme sehat + verifikasi terkalibrasi + privasi + AI sebagai penguat bukan pengganti + tanggung jawab & kejujuran + dasar yang kuat.",hint:"Gabungkan: konteks jelas + verifikasi + privasi + penguat bukan pengganti + tanggung jawab + kejujuran."},
{n:94,type:"open",micro:"Kapstone: memakai AI untuk sebuah tugas nyata dengan bijak",q:"Pilih tugas nyata yang sedang/akan kamu kerjakan (esai, proyek, persiapan ulangan, dsb.). Tuliskan rencana pemakaian AI yang bijak: (1) untuk bagian mana AI membantu & untuk bagian mana kamu kerjakan sendiri (+ alasan), (2) 2–3 instruksi spesifik yang akan kamu berikan (dengan konteks & batasan), (3) apa yang akan kamu verifikasi & bagaimana, (4) cara menjaga karya tetap milikmu & pemahamanmu terbangun, (5) kejujuran/pengungkapan sesuai aturan yang berlaku, (6) satu risiko pemakaian AI di tugas ini & cara kamu mengelolanya.",explain:"Kapstone menuntut penerapan menyeluruh: pembagian tugas yang menjaga pembelajaran, instruksi spesifik dengan batasan ('jangan tulis untukku'), verifikasi sumber asli, penjagaan kepenulisan & pemahaman, kejujuran sesuai aturan, & pengelolaan risiko konkret.",hint:"Bagian tersulit sering (1) — jujur pada dirimu tentang bagian mana yang sebenarnya melatihmu & harus kamu kerjakan sendiri.",sample:"Jawaban lengkap mengisi keenam bagian secara konkret. Contoh — tugas: esai argumentatif tentang wajib-tidaknya seragam sekolah. (1) AI membantu: menjelaskan struktur esai argumentatif, memberi contoh JENIS argumen dari dua sisi, memeriksa apakah aku melewatkan sudut pandang lawan, & mengecek tata bahasa draf-ku. Aku kerjakan sendiri: menentukan posisiku, menyusun argumen, menulis semua kalimat, mencari & memilih bukti. Alasan: tugas ini menilai kemampuan argumentasi & menulisku. (2) Instruksi: 'Aku murid kelas 9 menulis esai argumentatif ~500 kata. Beri aku 3 argumen terkuat UNTUK & 3 MELAWAN wajib seragam, sebagai poin singkat untuk kupertimbangkan — jangan menulis esai atau paragraf.' / 'Ini kerangkaku: [tempel]. Adakah kelemahan logika atau sudut pandang penting yang terlewat?' / 'Ini draf paragraf 2: [tempel]. Perbaiki hanya tata bahasa & kejelasan; jangan ubah argumen atau gayaku.' (3) Verifikasi: setiap data yang kupakai (mis. 'studi X menemukan...') kucek ke sumber aslinya; kalau AI menyebut studi, kupastikan studi itu ada & benar-benar mengatakan itu. (4) Menjaga milikku: aku menulis & merevisi semua kalimat sendiri dari pemahaman; AI hanya memberi poin pertimbangan & masukan tata bahasa; aku bisa menjelaskan setiap argumen & perubahan. (5) Aku ikuti aturan guru; bila diminta, aku tulis di akhir: 'Aku memakai AI untuk memeriksa kelengkapan sudut pandang & tata bahasa; seluruh argumen & tulisan adalah karyaku.' (6) Risiko: aku bisa tergoda memakai kalimat AI yang terdengar bagus → aku atasi dengan aturan 'tutup jawaban AI sebelum menulis, tulis dari pemahaman & suaraku sendiri'."},
{n:95,type:"mcq",micro:"Menilai alat AI yang mengklaim 'tanpa perlu verifikasi'",q:"Sebuah alat AI mengiklankan 'jawaban kami selalu akurat, tidak perlu diperiksa lagi'. Sikap yang tepat:",options:["Skeptis — tidak ada sistem AI yang bebas kesalahan; klaim seperti ini berlebihan & justru tanda bahaya","Percaya dan berhenti memverifikasi jawabannya, karena perusahaan sudah menjamin bahwa semua jawabannya akurat dan tidak pernah keliru","Beli langsung karena hemat waktu dan tidak perlu mencari tahu bukti klaimnya, sebab iklan yang berani menjanjikan pasti benar"],answer:0,explain:"Klaim kesempurnaan pada sistem AI hampir selalu keliru. Verifikasi untuk hal penting tetap perlu, apa pun klaim iklannya.",hint:"Apakah ada alat AI yang benar-benar tidak pernah salah?"},
{n:96,type:"mcq",micro:"Menyeimbangkan efisiensi & pembelajaran seiring waktu",q:"Untuk keterampilan yang sedang kamu bangun (mis. menulis argumen), pola pemakaian AI yang sehat seiring waktu:",options:["Makin lama makin bergantung pada AI, sampai akhirnya kamu tidak bisa lagi melakukan keterampilan itu sendiri tanpa bantuannya","Awalnya lebih banyak bantuan (memahami struktur & contoh), lalu KURANGI ketergantungan seiring kamu makin mahir — sampai bisa melakukannya baik tanpa AI","Ketergantungan yang sama besarnya selamanya sejak awal belajar, tanpa pernah dikurangi walaupun kamu sudah makin mahir seiring waktu"],answer:1,explain:"Bantuan yang baik seperti roda bantu sepeda: banyak di awal, lalu dilepas saat kamu bisa sendiri.",hint:"Kapan roda bantu sepeda seharusnya dilepas?"},
{n:97,type:"tf",micro:"Memakai AI dengan bijak adalah bentuk tanggung jawab",q:"Benar atau Salah: Cara seseorang memakai AI — jujur atau curang, memverifikasi atau menyebarkan kesalahan, memberdayakan diri atau melumpuhkan diri — adalah pilihan yang jadi tanggung jawabnya, bukan tanggung jawab alatnya.",answer:true,explain:"Alat tidak memilih bagaimana ia dipakai. Integritas, ketelitian, & kemandirian dalam memakai AI adalah pilihan & tanggung jawab pengguna.",hint:"Kalau seseorang memakai kalkulator untuk menyontek, salah kalkulatornya atau orangnya?"},
{n:98,type:"mcq",micro:"Sikap menutup",q:"Sikap paling berguna terhadap AI sebagai alat bantu:",options:["Serahkan semua pekerjaan dan pemikiranmu kepada AI, sebab ia lebih cepat dan tidak pernah lelah sehingga kamu tidak perlu lagi belajar apa pun, memeriksa jawabannya, atau menjaga privasi dan kejujuran dalam memakainya","Tolak AI sepenuhnya karena takut, tanpa mau mempelajari manfaat, risiko, dan cara memakainya dengan aman dan jujur di sekolah, sehingga kamu tidak pernah memperkuat belajar dan kerjamu dengan alat bantu apa pun","Manfaatkan untuk memperkuat belajar & kerja, arahkan dengan instruksi jelas, periksa yang penting, jaga privasi & kejujuran, & pastikan kamu tetap tumbuh sebagai pemikir — bukan menyerahkan pikiranmu"],answer:2,explain:"AI paling bernilai sebagai penguat kemampuan manusia yang dipakai dengan sadar, kritis, & bertanggung jawab.",hint:"Alat untuk memperkuat pikiranmu, atau untuk menggantikannya?"},
{n:99,type:"mcq",micro:"Prinsip inti",q:"Tiga prinsip inti memakai AI dengan bijak:",options:["Beri konteks yang jelas; verifikasi yang penting; jangan biarkan AI menggantikan usaha yang melatihmu atau tanggung jawab yang menjadi milikmu","Pakai sesering mungkin; percaya semua jawaban yang diberikan; dan sembunyikan pemakaiannya dari guru, teman, dan siapa pun yang bertanya nanti","Hindari sepenuhnya; jangan pernah bertanya apa pun kepadanya; dan anggap semua AI berbahaya sehingga tidak boleh dipelajari sama sekali"],answer:0,explain:"Konteks jelas + verifikasi terkalibrasi + AI sebagai penguat bukan pengganti (dengan kejujuran & tanggung jawab tetap padamu) adalah inti pemakaian bijak.",hint:"Gabungkan: konteks + verifikasi + penguat bukan pengganti."},
{n:100,type:"open",micro:"Kapstone: mengajarkan pemakaian AI yang bijak",q:"Tulis panduan singkat (8–10 poin) berjudul 'Memakai AI dengan Bijak' untuk teman sebayamu. Cakup: cara bertanya yang baik (konteks, tujuan, format), bahwa AI bisa keliru meski meyakinkan, cara & kapan memverifikasi, menjaga data pribadi, memakai AI untuk memahami bukan menyalin, menjaga karya & suara sendiri, kejujuran & aturan sekolah, menjaga keterampilan dasar, & kapan beralih ke sumber/orang lain. Gunakan bahasa yang jelas & contoh konkret.",explain:"Panduan baik menyederhanakan semua prinsip: bertanya berkonteks, skeptisisme sehat, verifikasi terkalibrasi, privasi, AI-untuk-memahami, menjaga kepenulisan & keterampilan, kejujuran & aturan, batas alat, & kapan butuh manusia — dengan contoh konkret & bahasa ramah.",hint:"Tiap poin harus bisa langsung dipraktikkan teman sebayamu besok — konkret, bukan abstrak.",sample:"Contoh panduan: 1) Beri konteks: sebut siapa kamu, untuk apa jawabannya, seberapa panjang, & format yang kamu mau ('Aku kelas 8, untuk poster, 5 poin singkat'). 2) Jawaban AI = tebakan pintar, BUKAN kebenaran pasti — ia bisa terdengar sangat yakin & tetap salah. 3) Cek fakta penting (angka, tanggal, nama, kutipan) di 2 sumber tepercaya sebelum dipakai; makin besar akibat kalau salah, makin ketat ceknya. 4) Jangan ketik data pribadi (nama keluarga lengkap, alamat, KTP, masalah pribadi yang sensitif) ke layanan AI. 5) Pakai AI untuk MENJELASKAN yang kamu bingung, lalu kerjakan sendiri — jangan minta jawaban jadi untuk disalin. 6) Tulis versi finalmu dengan kata-katamu sendiri dari pemahaman; kalau tulisannya tidak terdengar seperti kamu, tulis ulang. 7) Ikuti aturan gurumu soal AI; kalau ragu, tanya dulu; kalau diminta, jujur bilang bagaimana kamu memakainya. 8) Untuk soal yang menilai keterampilanmu (matematika, menulis), coba sendiri dulu sampai mentok — supaya kamu siap saat ujian tanpa AI. 9) Untuk hitungan yang harus tepat, pakai kalkulator; untuk hal yang sangat baru/lokal, cek sumber terkini — AI bisa ketinggalan. 10) Untuk keputusan pribadi berat atau dukungan emosional, bicara dengan orang tepercaya (keluarga, guru BK) — AI bukan penggantinya."},
];
